sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cc-organizer-page {
    padding: 28px;
    background: #f6f8fc;
    min-height: 100vh;
    color: #172033;
}

/* Header */

.cc-organizer-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
    margin-bottom: 28px;
}

.cc-organizer-eyebrow,
.cc-section-eyebrow {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.4px;
    color: #0b63ce;
}

.cc-organizer-title {
    margin: 7px 0 6px;
    font-size: 30px;
    font-weight: 700;
    color: #172033;
}

.cc-organizer-subtitle {
    margin: 0;
    color: #667085;
    font-size: 14px;
}

/* Create Event */

.cc-create-event-btn {
    display: inline-block;
    padding: 12px 20px;
    border-radius: 8px;
    background: #0b63ce;
    color: #ffffff !important;
    font-size: 14px;
    font-weight: 600;
    text-decoration: none !important;
    white-space: nowrap;
}

.cc-create-event-btn:hover {
    background: #084f9f;
}

/* Statistics */

.cc-organizer-stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 30px;
}

.cc-stat-card {
    padding: 20px;
    background: #ffffff;
    border: 1px solid #e5e9f2;
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(16, 24, 40, 0.04);
}

.cc-stat-label {
    font-size: 13px;
    color: #667085;
    margin-bottom: 10px;
}

.cc-stat-value {
    font-size: 28px;
    font-weight: 700;
    color: #172033;
}

/* Events */

.cc-events-section {
    background: #ffffff;
    border: 1px solid #e5e9f2;
    border-radius: 12px;
    padding: 24px;
}

.cc-section-header {
    margin-bottom: 22px;
}

.cc-section-header h2,
.cc-verification-panel h2 {
    margin: 6px 0;
    font-size: 21px;
    color: #172033;
}

.cc-section-header p {
    margin: 0;
    font-size: 13px;
    color: #667085;
}

/* Event card */

.cc-event-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.cc-organizer-event-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 18px;
    border: 1px solid #e5e9f2;
    border-radius: 9px;
    background: #ffffff;
}

.cc-event-main h3 {
    margin: 0 0 9px;
    font-size: 16px;
    color: #172033;
}

.cc-event-date,
.cc-event-location {
    display: inline-block;
    margin-right: 18px;
    font-size: 12px;
    color: #667085;
}

.cc-event-meta {
    display: flex;
    align-items: center;
    gap: 18px;
}

.cc-registration-count {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.cc-registration-count strong {
    font-size: 18px;
    color: #172033;
}

.cc-registration-count span {
    font-size: 11px;
    color: #667085;
}

/* Status */

.cc-status {
    padding: 6px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
}

.cc-status-verified {
    background: #e9f8ef;
    color: #18794e;
}

.cc-status-pending {
    background: #fff5dc;
    color: #9a6700;
}

.cc-status-rejected {
    background: #fdecec;
    color: #b42318;
}

/* Manage */

.cc-manage-btn {
    padding: 8px 13px;
    border: 1px solid #d5dbea;
    border-radius: 7px;
    color: #0b63ce !important;
    background: #ffffff;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none !important;
}

/* Empty */

.cc-empty-events {
    text-align: center;
    padding: 45px 20px;
    border: 1px dashed #d5dbea;
    border-radius: 9px;
}

.cc-empty-icon {
    font-size: 30px;
    margin-bottom: 10px;
}

.cc-empty-events h3 {
    margin: 0 0 7px;
    font-size: 17px;
}

.cc-empty-events p {
    margin: 0 0 18px;
    color: #667085;
    font-size: 13px;
}

.cc-empty-button {
    display: inline-block;
    padding: 9px 15px;
    border-radius: 7px;
    background: #0b63ce;
    color: #ffffff !important;
    text-decoration: none !important;
    font-size: 12px;
    font-weight: 600;
}

/* Verification */

.cc-verification-panel {
    margin-top: 20px;
    padding: 22px 24px;
    background: #ffffff;
    border: 1px solid #e5e9f2;
    border-radius: 12px;
}

.cc-verification-event {
    margin-top: 15px;
    padding: 15px;
    background: #f6f8fc;
    border-radius: 8px;
}

.cc-verification-event strong {
    font-size: 14px;
}

.cc-verification-event p {
    margin: 6px 0 0;
    font-size: 12px;
    color: #667085;
}

/* Mobile */

@media (max-width: 900px) {

    .cc-organizer-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .cc-organizer-event-card {
        align-items: flex-start;
        flex-direction: column;
    }

    .cc-event-meta {
        width: 100%;
        justify-content: space-between;
    }
}

@media (max-width: 600px) {

    .cc-organizer-page {
        padding: 18px;
    }

    .cc-organizer-header {
        flex-direction: column;
    }

    .cc-organizer-title {
        font-size: 24px;
    }

    .cc-organizer-stats {
        grid-template-columns: 1fr;
    }

    .cc-event-meta {
        flex-wrap: wrap;
    }
}

sp_widget.script:
(function() {

    data.publishedEvents = 0;
    data.totalRegistrations = 0;
    data.pendingEvents = 0;
    data.attendanceRate = 0;

    data.events = [];
    data.latestVerification = null;

    var currentUser = gs.getUserID();

    if (!currentUser) {
        return;
    }


    /*
     * ==========================================
     * 1. FIND CURRENT EVENT ORGANIZER PROFILE
     * ==========================================
     *
     * Event Organizer.organizer_name
     * points to the logged-in sys_user.
     *
     */

    var organizerProfile = new GlideRecord(
        'x_snc_campus_con_0_event_organizers'
    );

    organizerProfile.addQuery(
        'organizer_name',
        currentUser
    );

    organizerProfile.setLimit(1);
    organizerProfile.query();


    /*
     * If no Event Organizer profile exists,
     * there are no events to display.
     */

    if (!organizerProfile.next()) {
        return;
    }


    /*
     * Get the Event Organizer record sys_id.
     */

    var organizerSysId =
        organizerProfile.getUniqueValue();


    /*
     * ==========================================
     * 2. GET ORGANIZER'S EVENTS
     * ==========================================
     *
     * Events.organizer contains the
     * Event Organizer record sys_id.
     *
     */

    var events = new GlideRecord(
        'x_snc_campus_con_0_events'
    );

    events.addQuery(
        'organizer',
        organizerSysId
    );

    events.orderByDesc('event_date');
    events.query();


    var eventIds = [];


    while (events.next()) {

        var eventId =
            events.getUniqueValue();

        eventIds.push(eventId);


        /*
         * ==========================================
         * COUNT VERIFICATION STATUS
         * ==========================================
         */

        var verificationStatus =
            events.getValue(
                'verification_status'
            );


        if (verificationStatus == 'verified') {

            data.publishedEvents++;

        }


        if (verificationStatus == 'pending') {

            data.pendingEvents++;

        }


        /*
         * ==========================================
         * COUNT REGISTRATIONS
         * ==========================================
         */

        var registrationCount = 0;

        var registrations = new GlideRecord(
            'x_snc_campus_con_0_registrations'
        );

        registrations.addQuery(
            'event',
            eventId
        );

        registrations.query();


        while (registrations.next()) {

            registrationCount++;

        }


        data.totalRegistrations +=
            registrationCount;


        /*
         * ==========================================
         * ADD EVENT TO DASHBOARD
         * ==========================================
         */

        data.events.push({

            sys_id:
                eventId,

            eventName:
                events.getDisplayValue(
                    'event_name'
                ),

            eventDate:
                events.getDisplayValue(
                    'event_date'
                ),

            location:
                events.getDisplayValue(
                    'location'
                ),

            status:
                events.getDisplayValue(
                    'verification_status'
                ),

            registrationCount:
                registrationCount

        });


        /*
         * ==========================================
         * LATEST VERIFICATION
         * ==========================================
         */

        if (!data.latestVerification) {

            data.latestVerification = {

                eventName:
                    events.getDisplayValue(
                        'event_name'
                    ),

                status:
                    events.getDisplayValue(
                        'verification_status'
                    )

            };

        }

    }


    /*
     * ==========================================
     * 3. ATTENDANCE RATE
     * ==========================================
     *
     * Attendance Rate =
     * Attended Registrations /
     * Total Registrations × 100
     *
     */

    if (
        data.totalRegistrations > 0 &&
        eventIds.length > 0
    ) {

        var attendedCount = 0;

        var allRegistrations = new GlideRecord(
            'x_snc_campus_con_0_registrations'
        );

        allRegistrations.addQuery(
            'event',
            'IN',
            eventIds.join(',')
        );

        allRegistrations.query();


        while (allRegistrations.next()) {

            if (
                allRegistrations.getValue(
                    'registration_status'
                ) == 'attended'
            ) {

                attendedCount++;

            }

        }


        data.attendanceRate = Math.round(

            (
                attendedCount /
                data.totalRegistrations
            ) * 100

        );

    }

})();
